actions.script:
const out = ec.service.sync().name('org.moqui.call.CallRecordingServices.find#Recordings').parameters({callSessionId: callSessionId || null,
    pageIndex: Math.max(Number(pageIndex) || 0, 0), pageSize: 20}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({errors, recordingList: out.recordingList || [], recordingListCount: Number(out.recordingListCount || 0)})

const out = ec.service.sync().name('org.moqui.call.CallRecordingServices.get#RecordingFile').parameter('callRecordingSegmentId', callRecordingSegmentId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const refused = ec.message.hasError() || !out.location
ec.message.clearErrors()
if (refused) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && /^(audio|video)\//.test(out.contentType || ''))

const out = ec.service.sync().name('org.moqui.call.CallRecordingServices.delete#Recording').parameter('callRecordingId', callRecordingId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, deleted: !!out.deleted})
